const assert = require('assert');

function parseWikimediaUrl(currentUrl) {
  const fileNameMatch = currentUrl.match(/\/wiki\/([^?#&]+)/i);
  let rawFileName = fileNameMatch ? decodeURIComponent(fileNameMatch[1]) : '';
  // Strip any leading "File:" case-insensitively
  rawFileName = rawFileName.replace(/^File:/i, '').trim();
  const fileTitle = 'File:' + rawFileName.replace(/_/g, ' ');
  const cleanTitle = rawFileName.replace(/_/g, ' ').replace(/\.[a-z0-9]+$/i, '');
  return { fileTitle, cleanTitle };
}

const testCases = [
  'https://commons.wikimedia.org/wiki/File%3ACaenorhabditis_elegans_02.webm',
  'https://commons.wikimedia.org/wiki/File:Caenorhabditis_elegans_02.webm',
  'https://commons.wikimedia.org/wiki/Caenorhabditis_elegans_02.webm',
  'https://commons.wikimedia.org/wiki/File%3ASarychev_Peak_eruption_on_12_June_2009%2C_oblique_satellite_view.ogv'
];

for (const tc of testCases) {
  const res = parseWikimediaUrl(tc);
  console.log(tc, '->', res);
  assert.ok(!res.fileTitle.startsWith('File:File:'), 'Must not have File:File:');
  assert.ok(res.fileTitle.startsWith('File:'), 'Must start with File:');
  assert.ok(!res.cleanTitle.startsWith('File:'), 'Clean title must not have File:');
}
console.log('All parse tests passed!');

