const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

// 1. Load current rule
const rule = JSON.parse(fs.readFileSync('wikimedia-commons-video.json', 'utf8'));

// 2. Update detail_find_rule with the fix for File: prefix
rule.version = 3;
rule.detail_find_rule = `js:
var d = [];
var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
var fileNameMatch = currentUrl.match(/\\/wiki\\/([^?#&]+)/i);
var rawPart = fileNameMatch ? decodeURIComponent(fileNameMatch[1]) : '';
rawPart = rawPart.replace(/^File:/i, '').trim();
var fileTitle = 'File:' + rawPart.replace(/_/g, ' ');
var cleanTitle = rawPart.replace(/_/g, ' ').replace(/\\.[a-z0-9]+$/i, '');

var detailApi = 'https://commons.wikimedia.org/w/api.php?action=query&titles=' + encodeURIComponent(fileTitle) + '&prop=videoinfo|imageinfo&viprop=url|size|mime|derivatives&iiprop=url|size|mime|extmetadata&iiurlwidth=800&format=json';

var res = request(detailApi, {
  headers: {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
    'Accept': 'application/json'
  }
});

try {
  var json = typeof res === 'string' ? JSON.parse(res) : res;
  var pages = (json && json.query && json.query.pages) ? json.query.pages : {};
  var pageKey = Object.keys(pages)[0];
  var pageData = pageKey ? pages[pageKey] : {};
  var vinfo = (pageData.videoinfo && pageData.videoinfo.length > 0) ? pageData.videoinfo[0] : {};
  var iinfo = (pageData.imageinfo && pageData.imageinfo.length > 0) ? pageData.imageinfo[0] : {};

  var coverPic = (iinfo.thumburl || vinfo.url || iinfo.url || '');
  var durationSec = Math.round((vinfo.duration || iinfo.duration || 0));
  var durationStr = durationSec > 0 ? (Math.floor(durationSec / 60) + '分' + (durationSec % 60) + '秒') : '未知时长';
  var resolution = (vinfo.width && vinfo.height) ? (vinfo.width + 'x' + vinfo.height) : ((iinfo.width && iinfo.height) ? (iinfo.width + 'x' + iinfo.height) : '');

  var meta = (iinfo.extmetadata || {});
  var desc = (meta.ImageDescription && meta.ImageDescription.value) ? meta.ImageDescription.value.replace(/<[^>]+>/g, '').trim() : '';
  var artist = (meta.Artist && meta.Artist.value) ? meta.Artist.value.replace(/<[^>]+>/g, '').trim() : '';
  var license = (meta.LicenseShortName && meta.LicenseShortName.value) ? meta.LicenseShortName.value : '';

  var infoDesc = '时长: ' + durationStr + (resolution ? (' | 原画分辨率: ' + resolution) : '') + (license ? (' | 协议: ' + license) : '') + (artist ? ('\\n作者: ' + artist) : '') + (desc ? ('\\n简介: ' + desc) : '');

  // 1. 剧名保护首卡 (契约台账 #280)
  d.push({
    title: '剧名：' + cleanTitle,
    desc: infoDesc,
    pic_url: coverPic ? (coverPic + '@Referer=https://commons.wikimedia.org/') : '',
    url: currentUrl,
    col_type: 'pic_1_card'
  });

  // 2. 线路与清晰度选集
  d.push({
    title: '【清晰度播放线路】',
    col_type: 'text_1'
  });

  var derivatives = vinfo.derivatives || [];
  var foundStreams = [];
  if (derivatives && derivatives.length > 0) {
    for (var k = 0; k < derivatives.length; k++) {
      var stream = derivatives[k];
      var key = stream.transcodekey || '';
      var label = key ? key.replace(/\\.[^.]+$/, '') : (stream.width ? (stream.width + 'p') : ('清晰度 ' + (k + 1)));
      var sUrl = stream.src || '';
      if (sUrl) {
        foundStreams.push({
          title: '▶️ ' + label,
          url: sUrl + '@lazyRule=.js:(() => { return input + ";{User-Agent@Mozilla/5.0}"; })()',
          col_type: 'text_3'
        });
      }
    }
  }

  // 加入原画视频流
  var originalUrl = vinfo.url || iinfo.url || '';
  if (originalUrl) {
    foundStreams.push({
      title: '▶️ 原画播放 (' + (resolution || 'Original') + ')',
      url: originalUrl + '@lazyRule=.js:(() => { return input + ";{User-Agent@Mozilla/5.0}"; })()',
      col_type: 'text_3'
    });
  }

  if (foundStreams.length === 0) {
    // 兜底：尝试从页面或已知地址播放
    d.push({
      title: '⚠️ 暂无转码流 (点击尝试网页解析)',
      url: currentUrl,
      col_type: 'text_1'
    });
  } else {
    for (var m = 0; m < foundStreams.length; m++) {
      d.push(foundStreams[m]);
    }
  }

  // 3. 详细元数据信息文本展示
  if (desc || artist || license) {
    d.push({
      title: '【媒体详情与版权信息】',
      col_type: 'text_1'
    });
    if (artist) {
      d.push({
        title: '创作者: ' + artist,
        url: currentUrl,
        col_type: 'text_1'
      });
    }
    if (license) {
      d.push({
        title: '开源许可: ' + license,
        url: currentUrl,
        col_type: 'text_1'
      });
    }
    if (desc) {
      d.push({
        title: desc,
        url: currentUrl,
        col_type: 'text_1'
      });
    }
  }
} catch (e) {
  d.push({
    title: '解析出错: ' + e.message,
    col_type: 'text_1'
  });
}

setResult(d);`;

